const createDynamoDBClient = (accessKeyId: string, secretAccessKey: string, region: string) => {
  const client = new DynamoDBClient({
    credentials: { accessKeyId, secretAccessKey },
    region
  });

  return DynamoDBDocumentClient.from(client, {
    convertExtractValue: true
  });
};

let db: any = null;

