  if (!db) {
    // In production, use IAM roles instead of credentials
    db = await createDynamoDBClient(process.env.AWS_ACCESS_KEY_ID!, process.env.AWS_SECRET_ACCESS_KEY!, process.env.AWS_REGION!);
  }
  return db;
};

